poets_dict = {}

def add_poem(poet, poem_lines):
    if not poem_lines: return
    # remove lines that are just footnotes or numbers
    cleaned = []
    for line in poem_lines:
        line = re.sub(r'^\d+$', '', line)
        line = re.sub(r'^\d+\s+.*$', '', line)
        line = line.replace('238', '')
        if line.strip():
            cleaned.append(line.strip())
    poem_text = '\n'.join(cleaned).strip()
    if not poem_text: return
    
    if poet not in poets_dict:
        poets_dict[poet] = []
    poets_dict[poet].append(poem_text)

